int send_smb_request(struct TCP_Server_Info *server, struct smb_rqst *rqst) {
    int ret = 0;
    int corked = 0;
    size_t total_len = 0;
    struct kvec *iov = rqst->rq_iov;
    int iov_count = rqst->rq_nvec;
    struct page **pages = rqst->rq_pages;
    int page_count = rqst->rq_npages;
    size_t pages_sent = 0;

    if (!server || !server->sock) {
        return -EINVAL;
    }

    if (set_sock_flag(server->sock, TCP_CORK)) {
        corked = 1;
    }

    ret = smb_send_kvec(server, iov, iov_count);
    if (ret < 0) {
        goto out;
    }

    total_len += ret;

    for (int i = 0; i < page_count; i++) {
        size_t len = min(4096, (size_t)(PAGE_SIZE - (iov[i].iov_len % PAGE_SIZE)));
        ret = smb_send_page(server, pages[i], iov[i].iov_len % PAGE_SIZE, len, MSG_MORE);
        if (ret < 0) {
            goto out;
        }
        total_len += ret;
    }

    if (total_len != rqst->rq_totallen) {
        server->tcp_status = TCP_STATUS_NEED_RECONNECT;
    }

out:
    if (corked) {
        clear_sock_flag(server->sock, TCP_CORK);
    }

    if (ret < 0) {
        pr_err("Failed to send SMB request: %d\n", ret);
    }

    return ret;
}

int send_smb_request(struct TCP_Server_Info *server, struct smb_rqst *rqst)
{
    int ret = 0;
    struct kvec *iov = rqst->rq_iov;
    int iovcnt = rqst->rq_nvec;
    size_t total_len = 0;
    int i;

    if (!server || !server->ssocket) {
        return -ENOTCONN;
    }

    /* Set TCP_CORK to optimize send */
    if (setsockopt(server->ssocket, IPPROTO_TCP, TCP_CORK, &(int){1}, sizeof(int))) {
        ret = -errno;
        goto out;
    }

    /* Send initial SMB request */
    ret = smb_send_kvec(server->ssocket, iov, iovcnt);
    if (ret < 0)
        goto uncork;

    total_len = ret;

    /* Send additional pages if any */
    for (i = 0; i < rqst->rq_npages; i++) {
        struct page *page = rqst->rq_pages[i];
        int offset = rqst->rq_offsets[i];
        int length = rqst->rq_pageends[i] - offset;

        if (length <= 0)
            continue;

        ret = smb_sendpage(server->ssocket, page, offset, length, MSG_MORE);
        if (ret < 0)
            goto uncork;

        total_len += ret;
    }

uncork:
    /* Uncork the socket */
    if (setsockopt(server->ssocket, IPPROTO_TCP, TCP_CORK, &(int){0}, sizeof(int))) {
        int e = -errno;
        if (!ret)
            ret = e;
    }

    /* Check if total bytes sent match expected length */
    if (total_len != rqst->rq_length) {
        server->tcp_status = -ENOTCONN;
    }

out:
    if (ret < 0)
        printk(KERN_ERR "Failed to send SMB request: %d\n", ret);

    return ret;
}

int send_smb_request(struct TCP_Server_Info *server, struct smb_rqst *rqst)
{
    int result;
    size_t total_length;
    size_t bytes_sent = 0;
    int i;

    if (!server || !server->sock || !rqst)
        return -EINVAL;

    if (setsockopt(server->sock, IPPROTO_TCP, TCP_CORK, &(int){1}, sizeof(int)) < 0)
        return -errno;

    result = smb_send_kvec(server, rqst->iov, rqst->npages);
    if (result < 0)
        goto uncork_and_out;

    bytes_sent += result;

    for (i = 1; i < rqst->npages; i++) {
        result = smb_send_kvec(server, rqst->iov + i, 1);
        if (result < 0)
            goto uncork_and_out;

        bytes_sent += result;
    }

    total_length = rqst->total_len;
    if (bytes_sent != total_length) {
        server->tcp_status = -ENOLINK;
        result = -ENOLINK;
    }

uncork_and_out:
    setsockopt(server->sock, IPPROTO_TCP, TCP_CORK, &(int){0}, sizeof(int));

    if (result < 0) {
        printk(KERN_ERR "Failed to send SMB request: %d\n", result);
    }

    return result;
}

int smb_send_rqst(struct TCP_Server_Info *server, struct smb_rqst *rqst)
{
    int rc = 0;
    int i;
    size_t total_len = 0;

    if (!server || !server->sock || !rqst)
        return -EINVAL;

    if (sock_set_flag(server->sock, TCP_CORK))
        return -EFAULT;

    rc = smb_send_kvec(server, rqst->iov, rqst->n_iov, rqst->offset);
    if (rc < 0)
        goto out;

    total_len = rc;
    for (i = 0; i < rqst->nr_pages; i++) {
        rc = smb_sendpage(server, rqst->pages[i],
                          rqst->offsets[i], rqst->sizes[i], 0, MSG_DONTWAIT);
        if (rc < 0)
            goto out;
        total_len += rc;
    }

    if (sock_reset_flag(server->sock, TCP_CORK))
        return -EFAULT;

    if (total_len != rqst->total_len) {
        server->tcp_status = -1;
        cifs_dbg(VFS, "Sent %zu of %u bytes\n", total_len, rqst->total_len);
    }

out:
    if (rc < 0)
        cifs_dbg(VFS, "smb_send_rqst error %d\n", rc);

    return rc;
}

int send_smb_request(struct TCP_Server_Info *server, struct smb_rqst *rqst) {
    int ret = 0;
    size_t total_bytes = 0;
    struct kvec *iov;
    int iovcnt;
    int i;

    if (!server || !server->ssocket) {
        return -EINVAL;
    }

    ret = set_sock_opt(server->ssocket, TCP_CORK, 1);
    if (ret < 0)
        return ret;

    iov = rqst->rq_iov;
    iovcnt = rqst->rq_nvec;

    ret = smb_send_kvec(server, iov, iovcnt);
    if (ret < 0)
        goto out;

    total_bytes += ret;

    for (i = 0; i < rqst->rq_npages; i++) {
        ret = smb_send_kvec(server, (struct kvec *)rqst->rq_pages[i], 1);
        if (ret < 0)
            goto out;
        total_bytes += ret;
    }

out:
    set_sock_opt(server->ssocket, TCP_CORK, 0);

    if (total_bytes != rqst->rq_length) {
        server->tcp_status = SMB_TCP_DISCONNECT;
    }

    if (ret < 0) {
        printk(KERN_ERR "Failed to send SMB request: %d\n", ret);
    }

    return ret;
}
